import {Head, usePage} from '@inertiajs/react';
import Footer from "@/components/footer";
import {Toaster} from "@/components/ui/toast";
import Navigation2 from "@/components/navigation2";
import {lazy, Suspense, useEffect, useState} from 'react';
import EmergencyCta from "@/components/emergency-cta";

const Map = lazy(() => import("@/components/map"));

interface AppLayoutProps {
    children: React.ReactNode;
    title?: string;
    description?: string;
    image?: string;
}

export default function AppLayout({ children, title, description, image }: AppLayoutProps) {
    const [mounted, setMounted] = useState(false);
    const { url } = usePage();
    useEffect(() => setMounted(true), []);

    const defaultTitle = 'Teemane Heavy Haulage';
    const siteTitle = title ? `${title} - ${defaultTitle}` : defaultTitle;
    const siteDescription = description || "The only name trusted to perform on South Africa's most demanding worksites. Unmatched excellence in heavy haulage, abnormal transport, and specialised logistics across the SADC region.";
    // Need a default image, ideally the logo or a hero image
    const siteImage = image || '/images/logo.svg';
    // Construct full URL using window.location if available, fallback to path
    const fullUrl = typeof window !== 'undefined' ? window.location.href : url;

    return (
        <div className="min-h-screen flex flex-col bg-background text-foreground transition-colors duration-300 selection:bg-primary/75 selection:text-white">
            <Head>
                {title ? <title>{title}</title> : <title>{defaultTitle}</title>}
                <meta name="description" content={siteDescription} />

                {/* Open Graph / Facebook */}
                <meta property="og:type" content="website" />
                <meta property="og:url" content={fullUrl} />
                <meta property="og:title" content={siteTitle} />
                <meta property="og:description" content={siteDescription} />
                <meta property="og:image" content={siteImage} />

                {/* Twitter */}
                <meta name="twitter:card" content="summary_large_image" />
                <meta name="twitter:url" content={fullUrl} />
                <meta name="twitter:title" content={siteTitle} />
                <meta name="twitter:description" content={siteDescription} />
                <meta name="twitter:image" content={siteImage} />
            </Head>
            <a
                className="sr-only focus:not-sr-only focus:fixed focus:top-3 focus:left-3 focus:z-100 focus:px-4 focus:py-2 focus:rounded-xl focus:bg-background focus:text-foreground focus:shadow-lg focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 font-bold text-sm"
                href="#main"
            >
                Skip to main content
            </a>
            <Navigation2 />

            <main id="main" className="w-full flex-1 flex flex-col">
                {children}
            </main>
            <EmergencyCta />
            {mounted && (
                <Suspense fallback={null}>
                    <Map />
                </Suspense>
            )}

            <Footer />
            <Toaster />
        </div>
    );
}
